INSERT INTO project VALUES ('engie-automation', 'engineering', 'completed', 'ENGIE · Leanovia', '2023–2025', 'Java|Selenium|Appium|GitLab CI/CD|BrowserStack', 1);
INSERT INTO project_translation VALUES ('engie-automation', 'en', 'Building confidence at scale', 'A reusable foundation for web and mobile automation, designed to support several applications.', 'Several web and mobile applications needed consistent validation of important user journeys, with results that teams could understand and act on.', 'I developed and maintained a Java automation template with reusable scenarios, test data and reports. I integrated execution into GitLab CI/CD, ran cross-browser and mobile checks, and contributed to a container-based mobile testing setup.', 'The template supported several ENGIE projects. Automated reports helped teams inspect failures and investigate regressions.', 'A useful tool needs more than reliable code. Clear reports, reusable data and understandable conventions help other people work confidently.');
INSERT INTO project_translation VALUES ('engie-automation', 'fr', 'Construire la confiance à grande échelle', 'Un socle réutilisable d’automatisation web et mobile pour accompagner plusieurs applications.', 'Plusieurs applications web et mobiles avaient besoin de valider leurs parcours essentiels de manière cohérente, avec des résultats faciles à comprendre et à exploiter.', 'J’ai développé et maintenu un template Java avec des scénarios réutilisables, des jeux de données et des rapports. J’ai intégré les exécutions à GitLab CI/CD, réalisé les contrôles multi-navigateurs et mobiles et contribué à une infrastructure mobile conteneurisée.', 'Le template a accompagné plusieurs projets ENGIE. Les rapports automatisés facilitaient l’analyse des échecs et des régressions.', 'Un outil utile repose aussi sur des rapports clairs, des données réutilisables et des conventions compréhensibles pour les personnes qui l’utilisent.');
INSERT INTO project_translation VALUES ('engie-automation', 'es', 'Construir confianza a gran escala', 'Una base reutilizable de automatización web y móvil para diferentes aplicaciones.', 'Varias aplicaciones web y móviles necesitaban validar sus recorridos esenciales de manera coherente, con resultados comprensibles para los equipos.', 'Desarrollé y mantuve una plantilla Java con escenarios reutilizables, datos de prueba e informes. Integré su ejecución en GitLab CI/CD, realicé verificaciones en distintos navegadores y móviles y contribuí a una infraestructura móvil en contenedores.', 'La plantilla se utilizó en varios proyectos de ENGIE. Los informes automatizados ayudaban a analizar fallos y regresiones.', 'Una herramienta útil también necesita informes claros, datos reutilizables y convenciones fáciles de comprender para quienes la utilizan.');
INSERT INTO project VALUES ('mio-predictive-models', 'data', 'completed', 'Universidad Icesi · Cali', '2019', 'Python|Keras|Pandas|Plotly Dash|SQL', 2);
INSERT INTO project_translation VALUES ('mio-predictive-models', 'en', 'Making sense of movement', 'Predictive models and a data dashboard exploring bus travel times in Cali.', 'Cali’s M.I.O. transport system needed ways to anticipate travel times between stops. This academic project explored how historical operational data could support that understanding.', 'Working with Juan David Bolaños on our degree project, I contributed to data exploration, preparation and visualisation, and to the development and evaluation of neural-network models. The work included a dashboard comparing planned and observed journey times.', 'The research produced a documented first approximation for predicting upcoming travel times. It was an academic evaluation; operational deployment and improved passenger outcomes were not established.', 'Understanding the context and limitations of data is as important as selecting a model. Visualisation makes assumptions and patterns easier to discuss.');
INSERT INTO project_translation VALUES ('mio-predictive-models', 'fr', 'Comprendre le mouvement', 'Des modèles prédictifs et un tableau de bord pour explorer les temps de trajet des bus à Cali.', 'Le réseau M.I.O. de Cali avait besoin de mieux anticiper les temps entre les arrêts. Ce projet académique explorait l’apport des données historiques d’exploitation.', 'Avec Juan David Bolaños, dans le cadre de notre projet de fin d’études, j’ai contribué à l’exploration, à la préparation et à la visualisation des données, ainsi qu’au développement et à l’évaluation de réseaux de neurones. Un tableau de bord comparait les trajets planifiés et observés.', 'La recherche a produit une première approximation documentée des temps de trajet futurs. Il s’agissait d’une évaluation académique : un déploiement opérationnel et des bénéfices voyageurs n’ont pas été établis.', 'Comprendre le contexte et les limites des données compte autant que le choix du modèle. La visualisation facilite la discussion des hypothèses.');
INSERT INTO project_translation VALUES ('mio-predictive-models', 'es', 'Comprender el movimiento', 'Modelos predictivos y un tablero de datos para explorar los tiempos de viaje de los buses en Cali.', 'El sistema M.I.O. necesitaba anticipar mejor los tiempos entre paradas. Este proyecto académico exploró el aporte de los datos históricos de operación.', 'Junto con Juan David Bolaños, en nuestro proyecto de grado, contribuí a la exploración, preparación y visualización de datos, y al desarrollo y evaluación de redes neuronales. Un tablero comparaba los tiempos planeados con los observados.', 'La investigación produjo una primera aproximación documentada para predecir los tiempos de viaje. Fue una evaluación académica; no se establecieron un despliegue operativo ni mejoras para los pasajeros.', 'Comprender el contexto y las limitaciones de los datos es tan importante como elegir un modelo. La visualización facilita conversar sobre las hipótesis.');
INSERT INTO project VALUES ('marketing-ai', 'ai', 'in-progress', 'Diana Torres', 'In progress', 'Python|Streamlit|Generative AI', 3);
INSERT INTO project_translation VALUES ('marketing-ai', 'en', 'A thoughtful marketing assistant', 'An AI marketing assistant taking shape with Streamlit.', 'Explore how an AI assistant could make marketing work easier to structure and carry out.', 'I’m currently building this project with Streamlit. The interface, workflow and evaluation approach are still evolving.', 'Work in progress. A public demo, completed feature list and user results are not available yet.', 'This case study will grow with the project: decisions, iterations and lessons will be added as the work develops.');
INSERT INTO project_translation VALUES ('marketing-ai', 'fr', 'Un assistant marketing réfléchi', 'Un assistant marketing IA en cours de construction avec Streamlit.', 'Explorer comment un assistant IA pourrait faciliter l’organisation et la réalisation du travail marketing.', 'Je construis actuellement ce projet avec Streamlit. L’interface, le parcours et la démarche d’évaluation évoluent encore.', 'Projet en cours. La démonstration publique, les fonctionnalités définitives et les résultats utilisateurs ne sont pas encore disponibles.', 'Cette étude de cas s’enrichira progressivement des décisions, des itérations et des apprentissages du projet.');
INSERT INTO project_translation VALUES ('marketing-ai', 'es', 'Un asistente de marketing pensado con cuidado', 'Un asistente de marketing con IA en construcción con Streamlit.', 'Explorar cómo un asistente de IA podría facilitar la organización y realización del trabajo de marketing.', 'Actualmente estoy construyendo este proyecto con Streamlit. La interfaz, el recorrido y la evaluación siguen evolucionando.', 'Proyecto en curso. Aún no hay demostración pública, lista definitiva de funcionalidades ni resultados de usuarios.', 'Este caso de estudio crecerá con las decisiones, iteraciones y aprendizajes del proyecto.');
INSERT INTO project VALUES ('transunion-payments', 'engineering', 'completed', 'TransUnion', '2023', 'Java|REST APIs|PostgreSQL|Docker|SonarQube', 4);
INSERT INTO project_translation VALUES ('transunion-payments', 'en', 'Connecting everyday financial journeys', 'Java development and API integration for recurring payments.', 'Support recurring payments and the continuity of existing banking features across evolving web and mobile experiences.', 'As a Middle Developer, I developed recurring-payment modules in Java and integrated REST APIs. I contributed automated checks, technical documentation and code-quality analysis in an international team, working remotely from Cali.', 'My contributions covered payment functionality, API integration and automated delivery checks, supported by technical documentation for the team.', 'Reliable experiences depend on clear agreements between services and careful handling of the details users do not see.');
INSERT INTO project_translation VALUES ('transunion-payments', 'fr', 'Relier les parcours financiers du quotidien', 'Développement Java et intégration d’API pour les paiements récurrents.', 'Accompagner les paiements récurrents et la continuité des fonctionnalités bancaires lors de l’évolution des expériences web et mobiles.', 'En tant que Middle Developer, j’ai développé des modules de paiements récurrents en Java et intégré des API REST. J’ai contribué aux contrôles automatisés, à la documentation et à l’analyse de qualité du code, à distance depuis Cali dans une équipe internationale.', 'Mes contributions concernaient les fonctionnalités de paiement, les intégrations et les contrôles automatisés de livraison, accompagnés de documentation technique pour l’équipe.', 'La fiabilité d’un parcours dépend d’échanges clairs entre services et d’une attention aux détails invisibles pour les utilisateurs.');
INSERT INTO project_translation VALUES ('transunion-payments', 'es', 'Conectar los recorridos financieros cotidianos', 'Desarrollo Java e integración de API para pagos recurrentes.', 'Apoyar los pagos recurrentes y la continuidad de funcionalidades bancarias durante la evolución de experiencias web y móviles.', 'Como Middle Developer, desarrollé módulos de pagos recurrentes en Java e integré API REST. Contribuí a las verificaciones automatizadas, la documentación y el análisis de calidad del código, trabajando desde Cali con un equipo internacional.', 'Mis contribuciones abarcaron funcionalidades de pago, integraciones y verificaciones automatizadas de entrega, acompañadas de documentación técnica para el equipo.', 'La fiabilidad de una experiencia depende de acuerdos claros entre servicios y de cuidar los detalles que los usuarios no ven.');
INSERT INTO project VALUES ('public-service-performance', 'engineering', 'completed', 'Seine-Saint-Denis · Leanovia', '2025–2026', 'Java|Python|JMeter|Selenium|Elastic|Grafana', 5);
INSERT INTO project_translation VALUES ('public-service-performance', 'en', 'Understanding performance where it matters', 'Investigating application behaviour during a public-service platform upgrade.', 'Assess the behaviour of IODAS ASG, used by the solidarity department, during a change to its technical foundation.', 'I prepared representative load scenarios and test data, developed automation scripts and analysed results using JMeter and monitoring dashboards. I documented findings and shared recommendations with the project team.', 'The work produced performance comparisons, documented findings and recommendations to support the application upgrade.', 'Performance work connects technical investigation with real usage. A clear explanation can make a complex result useful to the whole team.');
INSERT INTO project_translation VALUES ('public-service-performance', 'fr', 'Comprendre la performance là où elle compte', 'Analyser le comportement d’une application lors de l’évolution d’un service public.', 'Évaluer le comportement d’IODAS ASG, utilisé par le pôle Solidarité, pendant le changement de son socle technique.', 'J’ai préparé des scénarios de charge et des jeux de données représentatifs, développé des scripts et analysé les résultats avec JMeter et des tableaux de supervision. J’ai documenté les constats et partagé mes recommandations.', 'Le travail a produit des comparaisons de performance, des analyses documentées et des recommandations pour accompagner l’évolution de l’application.', 'La performance relie l’investigation technique aux usages réels. Une explication claire rend les résultats utiles à toute l’équipe.');
INSERT INTO project_translation VALUES ('public-service-performance', 'es', 'Comprender el rendimiento donde importa', 'Analizar una aplicación durante la evolución de una plataforma de servicio público.', 'Evaluar el comportamiento de IODAS ASG, utilizado por el área de Solidaridad, durante el cambio de su base técnica.', 'Preparé escenarios de carga y datos representativos, desarrollé scripts y analicé los resultados con JMeter y tableros de supervisión. Documenté los hallazgos y compartí recomendaciones.', 'El trabajo produjo comparaciones de rendimiento, análisis documentados y recomendaciones para acompañar la evolución de la aplicación.', 'El rendimiento conecta la investigación técnica con los usos reales. Una explicación clara hace que los resultados sean útiles para todo el equipo.');
